sed -i -e "/CREATE TABLE FeeInvoices (/,/)/c\                    CREATE TABLE FeeInvoices (\n                        Id INT IDENTITY(1,1) PRIMARY KEY,\n                        InvoiceNumber NVARCHAR(50) NOT NULL UNIQUE,\n                        StudentId INT,\n                        StudentName NVARCHAR(200),\n                        StudentNumber NVARCHAR(50),\n                        ClassName NVARCHAR(100),\n                        FeeType NVARCHAR(100),\n                        OriginalAmount DECIMAL(18, 2) DEFAULT 0,\n                        DiscountAmount DECIMAL(18, 2) DEFAULT 0,\n                        FinalAmount DECIMAL(18, 2) NOT NULL CHECK (FinalAmount > 0),\n                        PaidAmount DECIMAL(18, 2) DEFAULT 0,\n                        RemainingAmount DECIMAL(18, 2) DEFAULT 0,\n                        DueDate DATE,\n                        Status NVARCHAR(50),\n                        CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),\n                        IsDeleted BIT DEFAULT 0\n                    )" src-vbnet/SchoolManagement.Data/DatabaseMigrationService.vb

sed -i -e "/CREATE TABLE PaymentReceipts (/,/)/c\                    CREATE TABLE PaymentReceipts (\n                        Id INT IDENTITY(1,1) PRIMARY KEY,\n                        ReceiptNumber NVARCHAR(50) NOT NULL UNIQUE,\n                        InvoiceNumber NVARCHAR(50),\n                        StudentName NVARCHAR(200),\n                        Amount DECIMAL(18, 2) NOT NULL CHECK (Amount > 0),\n                        ReceiptDate DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),\n                        PaymentMethod NVARCHAR(50),\n                        ReferenceNumber NVARCHAR(100),\n                        CashierName NVARCHAR(100),\n                        CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME()\n                    )" src-vbnet/SchoolManagement.Data/DatabaseMigrationService.vb
